#!/bin/sh
# Lance plane-mcp-server avec le jeton du rôle $1, lu dans le trousseau (secret-tool).
# PLANE_BASE_URL et PLANE_WORKSPACE_SLUG viennent de la config MCP (user ou projet).
role="$1"
[ -n "$role" ] || { echo "usage: plane-mcp <role>" >&2; exit 2; }
PLANE_API_KEY=<redacted> lookup service plane user "$role")" || exit 1
[ -n "$PLANE_API_KEY" ] || { echo "plane-mcp: aucun jeton pour '$role' dans le trousseau" >&2; exit 1; }
export PLANE_API_KEY
exec uvx plane-mcp-server stdio

