# Starts plane-mcp-server with the token of role $Role, read from Windows Credential Manager
# (generic credential "plane-<role>"). PLANE_BASE_URL and PLANE_WORKSPACE_SLUG come from the MCP config.
# stdout belongs to the MCP protocol: errors go to stderr only.
param([Parameter(Mandatory = $true, Position = 0)][string]$Role)

$ErrorActionPreference = 'Stop'

Add-Type -Namespace Native -Name Cred -MemberDefinition @'
[System.Runtime.InteropServices.DllImport("advapi32.dll", CharSet = System.Runtime.InteropServices.CharSet.Unicode, SetLastError = true)]
public static extern bool CredReadW(string target, int type, int flags, out System.IntPtr credential);
[System.Runtime.InteropServices.DllImport("advapi32.dll")]
public static extern void CredFree(System.IntPtr buffer);
'@

# CREDENTIAL layout (x64): blob size at offset 32 (uint32), blob pointer at offset 40.
function Get-StoredSecret([string]$Target) {
    $ptr = [IntPtr]::Zero
    if (-not [Native.Cred]::CredReadW($Target, 1, 0, [ref]$ptr)) { return $null }
    try {
        $size = [Runtime.InteropServices.Marshal]::ReadInt32($ptr, 32)
        $blob = [Runtime.InteropServices.Marshal]::ReadIntPtr($ptr, 40)
        return [Runtime.InteropServices.Marshal]::PtrToStringUni($blob, [int]($size / 2))
    } finally {
        [Native.Cred]::CredFree($ptr)
    }
}

$token = Get-StoredSecret "plane-$Role"
if ([string]::IsNullOrWhiteSpace($token)) {
    [Console]::Error.WriteLine("plane-mcp: no token for '$Role' in Credential Manager (target plane-$Role)")
    exit 1
}

$env:PLANE_API_KEY = REDACTED
# Python (uvx) validates with certifi, not the Windows store: trust the home Root CA explicitly.
$env:SSL_CERT_FILE = "$env:USERPROFILE\.claude\home-arpa-root-ca.pem"
& uvx plane-mcp-server stdio
exit $LASTEXITCODE

